/* global console, document, Excel, Office */

import * as msal from "@azure/msal-browser";
import { Client } from "@microsoft/microsoft-graph-client";

// Global variables
let msalInstance: msal.PublicClientApplication;
let graphClient: Client;
let columnMapping: { [key: string]: number } = {};
let currentUser: any;

// Initialize when Office is ready
Office.onReady((info) => {
    if (info.host === Office.HostType.Excel) {
        setupEventListeners();
    }
});

// Setup event listeners
function setupEventListeners() {
    // Login button
    document.getElementById("login-btn")?.addEventListener("click", login);
    document.getElementById("logout-btn")?.addEventListener("click", logout);

    // Column mapping
    document.getElementById("save-mapping-btn")?.addEventListener("click", saveColumnMapping);

    // User management
    document.getElementById("create-users-btn")?.addEventListener("click", createUsers);
    document.getElementById("assign-licenses-btn")?.addEventListener("click", assignLicenses);
    document.getElementById("add-to-team-btn")?.addEventListener("click", addToTeam);

    // Bulk operations
    document.getElementById("process-all-btn")?.addEventListener("click", processAllRows);

    // Tab navigation
    document.querySelectorAll(".tab-btn").forEach((btn) => {
        btn.addEventListener("click", (e) => {
            const target = e.target as HTMLElement;
            const tabName = target.getAttribute("data-tab");
            switchTab(tabName!);
        });
    });

    // Load column arrays when switching to column mapping tab
    document.querySelector('[data-tab="column-mapping"]')?.addEventListener("click", loadColumnArrays);
}

// Login function
async function login() {
    try {
        const clientId = (document.getElementById("client-id") as HTMLInputElement).value;
        const tenantId = (document.getElementById("tenant-id") as HTMLInputElement).value;
        const redirectUri = (document.getElementById("redirect-uri") as HTMLInputElement).value;

        if (!clientId || !tenantId) {
            showError("login-error", "Lütfen Application ID ve Tenant ID'sini girin.");
            return;
        }

        // Initialize MSAL
        const msalConfig = {
            auth: {
                clientId: clientId,
                authority: `https://login.microsoftonline.com/${tenantId}`,
                redirectUri: redirectUri,
            },
            cache: {
                cacheLocation: "sessionStorage",
                storeAuthStateInCookie: false,
            },
        };

        msalInstance = new msal.PublicClientApplication(msalConfig);

        // Acquire token
        const request = {
            scopes: [
                "https://graph.microsoft.com/User.ReadWrite.All",
                "https://graph.microsoft.com/Directory.ReadWrite.All",
                "https://graph.microsoft.com/Team.ReadBasic.All",
                "https://graph.microsoft.com/Organization.Read.All",
            ],
        };

        const response = await msalInstance.loginPopup(request);

        // Set active account after login
        if (response && response.account) {
            msalInstance.setActiveAccount(response.account);
        } else {
            // Get all accounts and set the first one
            const accounts = msalInstance.getAllAccounts();
            if (accounts && accounts.length > 0) {
                msalInstance.setActiveAccount(accounts[0]);
            }
        }

        // Initialize Graph client with proper auth provider
        graphClient = Client.init({
            authProvider: async (done) => {
                try {
                    const accounts = msalInstance.getAllAccounts();
                    const silentRequest = {
                        ...request,
                        account: accounts[0],
                    };
                    const token = await msalInstance.acquireTokenSilent(silentRequest);
                    done(null, token.accessToken);
                } catch (error) {
                    // Fallback to popup if silent fails
                    try {
                        const token = await msalInstance.acquireTokenPopup(request);
                        done(null, token.accessToken);
                    } catch (popupError) {
                        done(popupError, null);
                    }
                }
            },
        });

        // Get current user
        currentUser = await graphClient.api("/me").get();

        // Switch to main panel
        await loadColumnArrays();
        showPanel("main-panel");
        (document.getElementById("user-info") as HTMLElement).textContent = `Giriş: ${currentUser.userPrincipalName}`;

        // Load teams
        await loadTeams();

        clearError("login-error");
    } catch (error: any) {
        console.error("Login error:", error);
        showError("login-error", `Giriş başarısız: ${error.errorCode || error.message}`);
    }
}

// Logout function
function logout() {
    msalInstance.logout();
    showPanel("login-panel");
    columnMapping = {};
    currentUser = null;
}

// Show/hide panels
function showPanel(panelId: string) {
    document.querySelectorAll(".panel").forEach((panel) => {
        panel.classList.remove("active");
    });
    document.getElementById(panelId)?.classList.add("active");
}

// Switch tabs
function switchTab(tabName: string) {
    // Update buttons
    document.querySelectorAll(".tab-btn").forEach((btn) => {
        btn.classList.remove("active");
        if (btn.getAttribute("data-tab") === tabName) {
            btn.classList.add("active");
        }
    });

    // Update content
    document.querySelectorAll(".tab-content").forEach((content) => {
        content.classList.remove("active");
    });
    document.getElementById(tabName)?.classList.add("active");
}

// Load column arrays from Excel
async function loadColumnArrays() {
    try {
        await Excel.run(async (context) => {
            const sheet = context.workbook.worksheets.getActiveWorksheet();
            const usedRange = sheet.getUsedRange();
            usedRange.load("values, columnCount");
            await context.sync();

            const columnCount = usedRange.columnCount;
            const values = usedRange.values as any[][];

            // Get header row (first row)
            const headers = values && values.length > 0 ? values[0] : [];

            const selects = ["name-column", "email-column", "password-column"];

            selects.forEach((selectId) => {
                const select = document.getElementById(selectId) as HTMLSelectElement;
                select.innerHTML = '<option value="">Seçin...</option>';
                for (let i = 1; i <= columnCount; i++) {
                    const option = document.createElement("option");
                    option.value = (i - 1).toString();
                    // Use header name if available, otherwise use column letter
                    const headerName = headers[i - 1] ? String(headers[i - 1]).trim() : `Sütun ${String.fromCharCode(64 + i)}`;
                    option.textContent = headerName || `Sütun ${String.fromCharCode(64 + i)}`;
                    select.appendChild(option);
                }
            });

            // Restore saved mapping
            if (columnMapping.name !== undefined) {
                (document.getElementById("name-column") as HTMLSelectElement).value = columnMapping.name.toString();
                (document.getElementById("email-column") as HTMLSelectElement).value = columnMapping.email.toString();
                (document.getElementById("password-column") as HTMLSelectElement).value = columnMapping.password.toString();
            }
        });
    } catch (error) {
        console.error("Error loading columns:", error);
    }
}

// Save column mapping
function saveColumnMapping() {
    const nameCol = document.getElementById("name-column") as HTMLSelectElement;
    const emailCol = document.getElementById("email-column") as HTMLSelectElement;
    const passwordCol = document.getElementById("password-column") as HTMLSelectElement;

    if (!nameCol.value || !emailCol.value || !passwordCol.value) {
        showMessage("mapping-message", "Lütfen tüm sütunları seçin.", "error");
        return;
    }

    columnMapping = {
        name: parseInt(nameCol.value),
        email: parseInt(emailCol.value),
        password: parseInt(passwordCol.value),
    };

    showMessage("mapping-message", "Kolon eşleme başarıyla kaydedildi!", "success");
}

// Load teams
async function loadTeams() {
    try {
        const teams = await graphClient.api("/me/joinedTeams").get();
        const teamSelect = document.getElementById("team-id") as HTMLSelectElement;
        teamSelect.innerHTML = '<option value="">Ekip Seçin...</option>';

        if (teams.value && teams.value.length > 0) {
            teams.value.forEach((team: any) => {
                const option = document.createElement("option");
                option.value = team.id;
                option.textContent = team.displayName;
                teamSelect.appendChild(option);
            });
        } else {
            const option = document.createElement("option");
            option.value = "";
            option.textContent = "Henüz ekip bulunamadı";
            teamSelect.appendChild(option);
        }
    } catch (error) {
        console.error("Error loading teams:", error);
        const teamSelect = document.getElementById("team-id") as HTMLSelectElement;
        if (teamSelect) {
            teamSelect.innerHTML = '<option value="">Ekipler yüklenemedi. El ile Team ID girebilirsiniz.</option>';
        }
    }
}

// Get data from selected rows
async function getSelectedRowsData(domain?: string): Promise<any[]> {
    return new Promise((resolve, reject) => {
        Excel.run(async (context) => {
            try {
                const sheet = context.workbook.worksheets.getActiveWorksheet();

                // Try to use the currently selected range; if selection is empty or too small,
                // fallback to the used range (skipping header row)
                const selRange = context.workbook.getSelectedRange();
                selRange.load("values, rowCount, rowIndex");
                const usedRange = sheet.getUsedRange();
                usedRange.load("values, rowCount, rowIndex");
                await context.sync();

                let rows: any[] = [];
                let startRowIndex = 0;

                // If selection contains more than 1 row, use it; otherwise use usedRange (skip header)
                if (selRange.rowCount && selRange.rowCount > 1 && selRange.values && selRange.values.length > 0) {
                    rows = selRange.values as any[];
                    startRowIndex = selRange.rowIndex;
                } else if (usedRange && usedRange.values && usedRange.values.length > 1) {
                    // skip header row
                    const all = usedRange.values as any[][];
                    rows = all.slice(1);
                    startRowIndex = usedRange.rowIndex + 1;
                } else if (selRange.values && selRange.values.length > 0) {
                    // fallback to whatever the selection has
                    rows = selRange.values as any[];
                    startRowIndex = selRange.rowIndex;
                }

                const data: any[] = [];

                rows.forEach((row, idx) => {
                    if (columnMapping.email !== undefined) {
                        let email = row[columnMapping.email];
                        const name = row[columnMapping.name];

                        // If email is empty, generate from name + domain
                        if (!email || String(email).trim() === "") {
                            if (name && domain) {
                                const normalizedName = normalizeName(String(name));
                                email = `${normalizedName}@${domain}`;
                            } else if (name) {
                                const normalizedName = normalizeName(String(name));
                                email = normalizedName;
                            }
                        }

                        data.push({
                            name: name,
                            email: email,
                            password: row[columnMapping.password],
                            rowIndex: startRowIndex + idx,
                        });
                    }
                });

                resolve(data);
            } catch (error) {
                reject(error);
            }
        });
    });
}

// Create users
async function createUsers() {
    if (!columnMapping.email) {
        showMessage("mapping-message", "Lütfen önce kolon eşlemesini yapın!", "error");
        return;
    }

    const domainInput = (document.getElementById("domain-input") as HTMLInputElement).value?.trim();

    try {
        // Get users with domain parameter
        const users = await getSelectedRowsData(domainInput);

        if (users.length === 0) {
            showMessage("mapping-message", "Seçili satır bulunamadı!", "error");
            return;
        }

        // Highlight users that already exist and mark them on the user objects
        await highlightExistingUsers(users);

        const statusBox = document.getElementById("operation-status") as HTMLElement;
        statusBox.style.display = "block";
        statusBox.innerHTML = "<p>Kullanıcılar oluşturuluyor...</p>";

        let successCount = 0;
        let errorCount = 0;

        for (const user of users) {
            try {
                // Skip users that already exist
                if (user.exists) {
                    console.log("Kullanıcı zaten var, atlanıyor:", user.email);
                    continue;
                }
                // If email is still empty, skip (shouldn't happen but safety check)
                if (!user.email || String(user.email).trim() === "") {
                    console.error("Email oluşturulamadı:", user.name);
                    errorCount++;
                    continue;
                }

                if (!user.password || String(user.password).trim() === "") {
                    console.error(`Parola hatası: ${user.email}`);
                    errorCount++;
                    continue;
                }

                const email = String(user.email).trim();
                const mailNickname = email.split("@")[0];
                // If name is missing, derive a friendly display name from email
                const displayName = (user.name && String(user.name).trim() !== "")
                    ? String(user.name).trim()
                    : deriveDisplayNameFromEmail(email);

                const newUser = {
                    accountEnabled: true,
                    displayName: displayName,
                    mailNickname: mailNickname,
                    userPrincipalName: email,
                    usageLocation: "TR",
                    passwordProfile: {
                        forceChangePasswordNextSignIn: true,
                        password: String(user.password).trim(),
                    },
                };

                await graphClient.api("/users").post(newUser);
                successCount++;

                // Write the email to the Excel sheet
                if (user.rowIndex !== undefined) {
                    try {
                        await Excel.run(async (context) => {
                            const sheet = context.workbook.worksheets.getActiveWorksheet();
                            const cell = sheet.getCell(user.rowIndex, columnMapping.email);
                            cell.values = [[email]];
                            await context.sync();
                        });
                    } catch (writeError) {
                        console.error("Error writing email to Excel:", writeError);
                    }
                }
            } catch (error: any) {
                console.error(`Kullanıcı oluşturma hatası: ${user.email}`, error);
                errorCount++;
            }
        }

        statusBox.innerHTML = `<p>✓ ${successCount} kullanıcı oluşturuldu, ${errorCount} hata oluştu.</p>`;
    } catch (error) {
        console.error("Error creating users:", error);
        showMessage("mapping-message", "Kullanıcı oluşturma hatası!", "error");
    }
}

// Assign licenses
async function assignLicenses() {
    const domainInput = (document.getElementById("domain-input") as HTMLInputElement).value?.trim();

    try {
        // Get users with domain parameter
        const users = await getSelectedRowsData(domainInput);

        if (users.length === 0) {
            showMessage("mapping-message", "Seçili satır bulunamadı!", "error");
            return;
        }

        const statusBox = document.getElementById("operation-status") as HTMLElement;
        statusBox.style.display = "block";
        statusBox.innerHTML = "<p>Lisanslar atanıyor...</p>";

        let successCount = 0;
        let errorCount = 0;

        for (const user of users) {
            try {
                // Validate email
                if (!user.email || String(user.email).trim() === "") {
                    errorCount++;
                    continue;
                }

                const email = String(user.email).trim();
                const userObj = await graphClient
                    .api(`/users?$filter=userPrincipalName eq '${email}'`)
                    .get();

                if (userObj.value && userObj.value.length > 0) {
                    const userId = userObj.value[0].id;

                    // Always use STANDARDWOFFPACK_STUDENT (Student license)
                    const skuId = "314c4481-f395-4525-be8b-2ec4bb1e9d91";

                    await graphClient.api(`/users/${userId}/assignLicense`).post({
                        addLicenses: [
                            {
                                skuId: skuId,
                            },
                        ],
                        removeLicenses: [],
                    });
                    successCount++;
                }
            } catch (error: any) {
                console.error(`Lisans atama hatası: ${user.email}`, error);
                errorCount++;
            }
        }

        statusBox.innerHTML = `<p>✓ ${successCount} kullanıcıya lisans atandı, ${errorCount} hata oluştu.</p>`;
    } catch (error) {
        console.error("Error assigning licenses:", error);
        showMessage("mapping-message", "Lisans atama hatası!", "error");
    }
}

// Normalize name: convert Turkish chars to ASCII, lowercase, remove spaces
function normalizeName(name: string): string {
    if (!name) return "";

    // Turkish character mapping
    const turkishMap: { [key: string]: string } = {
        ç: "c", Ç: "C",
        ğ: "g", Ğ: "G",
        ı: "i", I: "I",
        i: "i", İ: "I",
        ö: "o", Ö: "O",
        ş: "s", Ş: "S",
        ü: "u", Ü: "U",
    };

    // Replace Turkish characters
    let normalized = name.split("").map(char => turkishMap[char] || char).join("");

    // Convert to lowercase, remove spaces and special characters
    normalized = normalized.toLowerCase().replace(/\s+/g, "").replace(/[^a-z0-9]/g, "");

    return normalized;
}

// Derive a friendly display name from an email local-part
function deriveDisplayNameFromEmail(email: string): string {
    if (!email) return "";
    const local = String(email).split("@")[0] || email;
    // Replace common separators with spaces
    const words = local.replace(/[._\-]+/g, ' ').split(' ').filter(Boolean);
    // Capitalize each word
    const friendly = words.map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    return friendly || local;
}

// Check which users already exist in Azure AD and highlight their rows in Excel (purple)
async function highlightExistingUsers(users: any[]) {
    if (!users || users.length === 0) return;

    const existingRowIndices: number[] = [];

    for (const user of users) {
        const email = user.email ? String(user.email).trim() : "";
        if (!email) continue;

        try {
            const resp = await graphClient.api(`/users?$filter=userPrincipalName eq '${email}'`).get();
            if (resp && resp.value && resp.value.length > 0) {
                user.exists = true;
                if (user.rowIndex !== undefined) existingRowIndices.push(user.rowIndex);
            }
        } catch (error) {
            console.error("Error checking existing user:", email, error);
        }
    }

    if (existingRowIndices.length === 0) return;

    try {
        await Excel.run(async (context) => {
            const sheet = context.workbook.worksheets.getActiveWorksheet();
            const used = sheet.getUsedRange();
            used.load('columnCount');
            await context.sync();
            const colCount = used.columnCount || 10;

            for (const rowIndex of existingRowIndices) {
                const range = sheet.getRangeByIndexes(rowIndex, 0, 1, colCount);
                range.format.fill.color = '#800080'; // purple
            }

            await context.sync();
        });
    } catch (ex) {
        console.error('Error highlighting existing rows in Excel:', ex);
    }
}

// Add to team
async function addToTeam() {
    const teamId = (document.getElementById("team-id") as HTMLSelectElement).value;

    if (!teamId) {
        showMessage("mapping-message", "Lütfen bir ekip seçin!", "error");
        return;
    }

    if (!columnMapping.email) {
        showMessage("mapping-message", "Lütfen önce kolon eşlemesini yapın!", "error");
        return;
    }

    const domainInput = (document.getElementById("domain-input") as HTMLInputElement).value?.trim();

    try {
        // Get users with domain parameter
        const users = await getSelectedRowsData(domainInput);

        if (users.length === 0) {
            showMessage("mapping-message", "Seçili satır bulunamadı!", "error");
            return;
        }

        const statusBox = document.getElementById("operation-status") as HTMLElement;
        statusBox.style.display = "block";
        statusBox.innerHTML = "<p>Kullanıcılar ekibe ekleniyor...</p>";

        let successCount = 0;
        let errorCount = 0;

        for (const user of users) {
            try {
                // Validate email
                if (!user.email || String(user.email).trim() === "") {
                    errorCount++;
                    continue;
                }

                const email = String(user.email).trim();
                const userObj = await graphClient
                    .api(`/users?$filter=userPrincipalName eq '${email}'`)
                    .get();

                if (userObj.value && userObj.value.length > 0) {
                    const userId = userObj.value[0].id;

                    await graphClient.api(`/teams/${teamId}/members`).post({
                        "@odata.type": "#microsoft.graph.aadUserConversationMember",
                        "user@odata.bind": `https://graph.microsoft.com/v1.0/users/${userId}`,
                    });
                    successCount++;
                }
            } catch (error: any) {
                console.error(`Ekibe ekleme hatası: ${user.email}`, error);
                errorCount++;
            }
        }

        statusBox.innerHTML = `<p>✓ ${successCount} kullanıcı ekibe eklendi, ${errorCount} hata oluştu.</p>`;
    } catch (error) {
        console.error("Error adding to team:", error);
        showMessage("mapping-message", "Ekibe ekleme hatası!", "error");
    }
}

// Process all rows
async function processAllRows() {
    // This can be customized based on your needs
    // For now, it will create users, assign licenses, and add to team
    const operationLog = document.getElementById("operation-log") as HTMLElement;
    operationLog.innerHTML = '<div class="log-entry info">İşlem başlatılıyor...</div>';

    const domainInput = (document.getElementById("domain-input") as HTMLInputElement).value?.trim();

    try {
        const users = await getSelectedRowsData(domainInput);

        if (users.length === 0) {
            operationLog.innerHTML += '<div class="log-entry error">Seçili satır bulunamadı!</div>';
            return;
        }

        operationLog.innerHTML += `<div class="log-entry info">Toplam ${users.length} satır bulundu</div>`;

        // Create users
        operationLog.innerHTML += '<div class="log-entry info">Adım 1: Kullanıcılar oluşturuluyor...</div>';
        await createUsers();

        // Assign licenses
        operationLog.innerHTML += '<div class="log-entry info">Adım 2: Lisanslar atanıyor...</div>';
        await assignLicenses();

        // Add to team
        operationLog.innerHTML += '<div class="log-entry info">Adım 3: Ekibe ekleme işlemi yapılıyor...</div>';
        await addToTeam();

        operationLog.innerHTML += '<div class="log-entry success">✓ Tüm işlemler tamamlandı!</div>';
    } catch (error) {
        console.error("Error processing rows:", error);
        operationLog.innerHTML += '<div class="log-entry error">✗ İşlem sırasında hata oluştu!</div>';
    }
}

// Helper functions
function showError(elementId: string, message: string) {
    const element = document.getElementById(elementId) as HTMLElement;
    element.textContent = message;
    element.style.display = "block";
}

function clearError(elementId: string) {
    const element = document.getElementById(elementId) as HTMLElement;
    element.style.display = "none";
}

function showMessage(elementId: string, message: string, type: "success" | "error" | "info" = "info") {
    const element = document.getElementById(elementId) as HTMLElement;
    element.textContent = message;
    element.className = "info-message";
    if (type === "error") {
        element.className = "error-message";
    }
    element.style.display = "block";
}
